# Cache-aware Merge Sort with single scratch buffer, sorted-skip & Insertion cutoff
def merge_sort(arr: list[int]) -> None:
    scratch = [0] * len(arr)
    def _sort(lo: int, hi: int) -> None:
        if hi - lo <= 16:
            for i in range(lo + 1, hi + 1):
                key, j = arr[i], i - 1
                while j >= lo and arr[j] > key:
                    arr[j + 1] = arr[j]; j -= 1
                arr[j + 1] = key
            return
        mid = lo + (hi - lo) // 2
        _sort(lo, mid)
        _sort(mid + 1, hi)
        if arr[mid] <= arr[mid + 1]:
            return  # Already ordered; skip merge in O(1)
        scratch[lo:hi + 1] = arr[lo:hi + 1]
        i, j, k = lo, mid + 1, lo
        while i <= mid and j <= hi:
            if scratch[i] <= scratch[j]: arr[k] = scratch[i]; i += 1
            else: arr[k] = scratch[j]; j += 1
            k += 1
        while i <= mid: arr[k] = scratch[i]; i += 1; k += 1
    if len(arr) > 1: _sort(0, len(arr) - 1)
